20	import {createSymbol, normalizeSymbolOffset, normalizeSymbolSize} from '../../util/symbol';
21	import {Group, Path} from '../../util/graphic';
22	import { enterEmphasis, leaveEmphasis, toggleHoverEmphasis } from '../../util/states';
23	import SymbolClz from './Symbol';
24	import SeriesData from '../../data/SeriesData';
25	import type { ZRColor, ECElement } from '../../util/types';
26	import type Displayable from 'zrender/src/graphic/Displayable';
27	import { SymbolDrawItemModelOption } from './SymbolDraw';
28	
29	interface RippleEffectCfg {
30	    showEffectOn?: 'emphasis' | 'render'
31	    rippleScale?: number
32	    brushType?: 'fill' | 'stroke'
33	    period?: number
34	    effectOffset?: number
35	    z?: number
36	    zlevel?: number
37	    symbolType?: string
38	    color?: ZRColor
39	    rippleEffectColor?: ZRColor,
40	    rippleNumber?: number
41	}
42	
43	function updateRipplePath(rippleGroup: Group, effectCfg: RippleEffectCfg) {
44	    const color = effectCfg.rippleEffectColor || effectCfg.color;
45	    rippleGroup.eachChild(function (ripplePath: Displayable) {
46	        ripplePath.attr({
47	            z: effectCfg.z,
48	            zlevel: effectCfg.zlevel,
49	            style: {
50	                stroke: effectCfg.brushType === 'stroke' ? color : null,
51	                fill: effectCfg.brushType === 'fill' ? color : null
52	            }
53	        });
54	    });
55	}
56	
57	class EffectSymbol extends Group {
58	
59	    private _effectCfg: RippleEffectCfg;
60	
61	    constructor(data: SeriesData, idx: number) {
62	        super();
63	
64	        const symbol = new SymbolClz(data, idx);
65	        const rippleGroup = new Group();
66	        this.add(symbol);
67	        this.add(rippleGroup);
68	
69	        this.updateData(data, idx);
70	    }
71	
72	
73	    stopEffectAnimation() {
74	        (this.childAt(1) as Group).removeAll();
75	    }
76	
77	    startEffectAnimation(effectCfg: RippleEffectCfg) {
78	        const symbolType = effectCfg.symbolType;
79	        const color = effectCfg.color;
80	        const rippleNumber = effectCfg.rippleNumber;
81	        const rippleGroup = this.childAt(1) as Group;
82	
83	        for (let i = 0; i < rippleNumber; i++) {
84	            // If width/height are set too small (e.g., set to 1) on ios10
85	            // and macOS Sierra, a circle stroke become a rect, no matter what
86	            // the scale is set. So we set width/height as 2. See #4136.
87	            const ripplePath = createSymbol(
88	                symbolType, -1, -1, 2, 2, color
89	            );
90	            ripplePath.attr({
91	                style: {
92	                    strokeNoScale: true
93	                },
94	                z2: 99,
95	                silent: true,
96	                scaleX: 0.5,
97	                scaleY: 0.5
98	            });
99	
100	            const delay = -i / rippleNumber * effectCfg.period + effectCfg.effectOffset;
101	            ripplePath.animate('', true)
102	                .when(effectCfg.period, {
103	                    scaleX: effectCfg.rippleScale / 2,
104	                    scaleY: effectCfg.rippleScale / 2
105	                })
106	                .delay(delay)
107	                .start();
108	            ripplePath.animateStyle(true)
109	                .when(effectCfg.period, {
110	                    opacity: 0
111	                })
112	                .delay(delay)
113	                .start();
114	
115	            rippleGroup.add(ripplePath);
116	        }
117	
118	        updateRipplePath(rippleGroup, effectCfg);
119	    }
120	
121	    /**
122	     * Update effect symbol
123	     */
124	    updateEffectAnimation(effectCfg: RippleEffectCfg) {
125	        const oldEffectCfg = this._effectCfg;
126	        const rippleGroup = this.childAt(1) as Group;
127	
128	        // Must reinitialize effect if following configuration changed
129	        const DIFFICULT_PROPS = ['symbolType', 'period', 'rippleScale', 'rippleNumber'] as const;
130	        for (let i = 0; i < DIFFICULT_PROPS.length; i++) {
131	            const propName = DIFFICULT_PROPS[i];
132	            if (oldEffectCfg[propName] !== effectCfg[propName]) {
133	                this.stopEffectAnimation();
134	                this.startEffectAnimation(effectCfg);
135	                return;
136	            }
137	        }
138	
139	        updateRipplePath(rippleGroup, effectCfg);
140	    }
141	
142	    /**
143	     * Highlight symbol
144	     */
145	    highlight() {
146	        enterEmphasis(this);
147	    }
148	
149	    /**
150	     * Downplay symbol
151	     */
152	    downplay() {
153	        leaveEmphasis(this);
154	    }
155	
156	    getSymbolType() {
157	        const symbol = this.childAt(0) as SymbolClz;
158	        return symbol && symbol.getSymbolType();
159	    }
160	
161	    /**
162	     * Update symbol properties
163	     */
164	    updateData(data: SeriesData, idx: number) {
165	        const seriesModel = data.hostModel;
166	
167	        (this.childAt(0) as SymbolClz).updateData(data, idx);
168	
169	        const rippleGroup = this.childAt(1);
170	        const itemModel = data.getItemModel<SymbolDrawItemModelOption>(idx);
171	        const symbolType = data.getItemVisual(idx, 'symbol');
172	        const symbolSize = normalizeSymbolSize(data.getItemVisual(idx, 'symbolSize'));
173	
174	        const symbolStyle = data.getItemVisual(idx, 'style');
175	        const color = symbolStyle && symbolStyle.fill;
176	        const emphasisModel = itemModel.getModel('emphasis');
177	
178	        rippleGroup.setScale(symbolSize);
179	
180	        rippleGroup.traverse(function (ripplePath: Path) {
181	            ripplePath.setStyle('fill', color);
182	        });
183	
184	        const symbolOffset = normalizeSymbolOffset(data.getItemVisual(idx, 'symbolOffset'), symbolSize);
185	        if (symbolOffset) {
186	            rippleGroup.x = symbolOffset[0];
187	            rippleGroup.y = symbolOffset[1];
188	        }
189	
190	        const symbolRotate = data.getItemVisual(idx, 'symbolRotate');
191	        rippleGroup.rotation = (symbolRotate || 0) * Math.PI / 180 || 0;
192	
193	        const effectCfg: RippleEffectCfg = {};
194	
195	        effectCfg.showEffectOn = seriesModel.get('showEffectOn');
196	        effectCfg.rippleScale = itemModel.get(['rippleEffect', 'scale']);
197	        effectCfg.brushType = itemModel.get(['rippleEffect', 'brushType']);
198	        effectCfg.period = itemModel.get(['rippleEffect', 'period']) * 1000;
199	        effectCfg.effectOffset = idx / data.count();
200	        effectCfg.z = seriesModel.getShallow('z') || 0;
201	        effectCfg.zlevel = seriesModel.getShallow('zlevel') || 0;
202	        effectCfg.symbolType = symbolType;
203	        effectCfg.color = color;
204	        effectCfg.rippleEffectColor = itemModel.get(['rippleEffect', 'color']);
205	        effectCfg.rippleNumber = itemModel.get(['rippleEffect', 'number']);
206	
207	        if (effectCfg.showEffectOn === 'render') {
208	            this._effectCfg
209	                ? this.updateEffectAnimation(effectCfg)
210	                : this.startEffectAnimation(effectCfg);
211	
212	            this._effectCfg = effectCfg;
213	        }
214	        else {
215	            // Not keep old effect config
216	            this._effectCfg = null;
217	
218	            this.stopEffectAnimation();
219	
220	            (this as ECElement).onHoverStateChange = (toState) => {
221	                if (toState === 'emphasis') {
222	                    if (effectCfg.showEffectOn !== 'render') {
223	                        this.startEffectAnimation(effectCfg);
224	                    }
225	                }
226	                else if (toState === 'normal') {
227	                    if (effectCfg.showEffectOn !== 'render') {
228	                        this.stopEffectAnimation();
229	                    }
230	                }
231	            };
232	        }
233	
234	        this._effectCfg = effectCfg;
235	
236	        toggleHoverEmphasis(
237	            this,
238	            emphasisModel.get('focus'),
239	            emphasisModel.get('blurScope'),
240	            emphasisModel.get('disabled')
241	        );
242	    };
243	
244	    fadeOut(cb: () => void) {
245	        cb && cb();
246	    };
247	
248	}
249	
250	export default EffectSymbol;

