52	type LineList = SeriesData<SeriesModel, LineDataVisual>;
53	
54	export interface LineLabel extends graphic.Text {
55	    lineLabelOriginalOpacity: number
56	}
57	
58	interface InnerLineLabel extends LineLabel {
59	    __align: TextStyleProps['align']
60	    __verticalAlign: TextStyleProps['verticalAlign']
61	    __position: LineLabelOption['position']
