65	function makeSymbolTypeKey(symbolCategory: 'fromSymbol' | 'toSymbol') {
66	    return '_' + symbolCategory + 'Type' as '_fromSymbolType' | '_toSymbolType';
67	}
68	function makeSymbolTypeValue(name: 'fromSymbol' | 'toSymbol', lineData: LineList, idx: number) {
69	    const symbolType = lineData.getItemVisual(idx, name);
70	    if (!symbolType || symbolType === 'none') {
71	        return symbolType;
72	    }
73	    const symbolSize = lineData.getItemVisual(idx, name + 'Size' as 'fromSymbolSize' | 'toSymbolSize');
74	    const symbolRotate = lineData.getItemVisual(idx, name + 'Rotate' as 'fromSymbolRotate' | 'toSymbolRotate');
75	    const symbolOffset = lineData.getItemVisual(idx, name + 'Offset' as 'fromSymbolOffset' | 'toSymbolOffset');
76	    const symbolKeepAspect = lineData.getItemVisual(idx,
77	        name + 'KeepAspect' as 'fromSymbolKeepAspect' | 'toSymbolKeepAspect');
78	    const symbolSizeArr = symbolUtil.normalizeSymbolSize(symbolSize);
79	
80	    const symbolOffsetArr = symbolUtil.normalizeSymbolOffset(symbolOffset || 0, symbolSizeArr);
81	
82	    return symbolType + symbolSizeArr + symbolOffsetArr + (symbolRotate || '') + (symbolKeepAspect || '');
83	}
84	
85	/**
86	 * @inner
87	 */
88	function createSymbol(name: 'fromSymbol' | 'toSymbol', lineData: LineList, idx: number) {
89	    const symbolType = lineData.getItemVisual(idx, name);
90	    if (!symbolType || symbolType === 'none') {
91	        return;
92	    }
93	
94	    const symbolSize = lineData.getItemVisual(idx, name + 'Size' as 'fromSymbolSize' | 'toSymbolSize');
95	    const symbolRotate = lineData.getItemVisual(idx, name + 'Rotate' as 'fromSymbolRotate' | 'toSymbolRotate');
96	    const symbolOffset = lineData.getItemVisual(idx, name + 'Offset' as 'fromSymbolOffset' | 'toSymbolOffset');
97	    const symbolKeepAspect = lineData.getItemVisual(idx,
98	        name + 'KeepAspect' as 'fromSymbolKeepAspect' | 'toSymbolKeepAspect');
99	
100	    const symbolSizeArr = symbolUtil.normalizeSymbolSize(symbolSize);
101	
102	    const symbolOffsetArr = symbolUtil.normalizeSymbolOffset(symbolOffset || 0, symbolSizeArr);
103	
104	    const symbolPath = symbolUtil.createSymbol(
105	        symbolType,
106	        -symbolSizeArr[0] / 2 + (symbolOffsetArr as number[])[0],
107	        -symbolSizeArr[1] / 2 + (symbolOffsetArr as number[])[1],
108	        symbolSizeArr[0],
109	        symbolSizeArr[1],
110	        null,
111	        symbolKeepAspect
112	    );
113	
114	    (symbolPath as LineECSymbol).__specifiedRotation = symbolRotate == null || isNaN(symbolRotate)
115	        ? void 0
116	        : +symbolRotate * Math.PI / 180 || 0;
117	
118	    symbolPath.name = name;
119	
120	    return symbolPath;
121	}
122	
123	function createLine(points: number[][]) {
124	    const line = new ECLinePath({
125	        name: 'line',
126	        subPixelOptimize: true
127	    });
128	    setLinePoints(line.shape, points);
129	    return line;
130	}
131	
132	function setLinePoints(targetShape: ECLinePath['shape'], points: number[][]) {
133	    type CurveShape = ECLinePath['shape'] & {
134	        cpx1: number
135	        cpy1: number
136	    };
137	
138	    targetShape.x1 = points[0][0];
139	    targetShape.y1 = points[0][1];
140	    targetShape.x2 = points[1][0];
141	    targetShape.y2 = points[1][1];
142	    targetShape.percent = 1;
143	
144	    const cp1 = points[2];
145	    if (cp1) {
146	        (targetShape as CurveShape).cpx1 = cp1[0];
147	        (targetShape as CurveShape).cpy1 = cp1[1];
148	    }
149	    else {
150	        (targetShape as CurveShape).cpx1 = NaN;
151	        (targetShape as CurveShape).cpy1 = NaN;
152	    }
153	}
