354	    beforeUpdate() {
355	        const lineGroup = this;
356	        const symbolFrom = lineGroup.childOfName('fromSymbol') as ECSymbol;
357	        const symbolTo = lineGroup.childOfName('toSymbol') as ECSymbol;
358	        const label = lineGroup.getTextContent() as InnerLineLabel;
359	        // Quick reject
360	        if (!symbolFrom && !symbolTo && (!label || label.ignore)) {
361	            return;
362	        }
363	
364	        let invScale = 1;
365	        let parentNode = this.parent;
366	        while (parentNode) {
367	            if (parentNode.scaleX) {
368	                invScale /= parentNode.scaleX;
369	            }
370	            parentNode = parentNode.parent;
371	        }
372	
373	        const line = lineGroup.childOfName('line') as ECLinePath;
374	        // If line not changed
375	        // FIXME Parent scale changed
376	        if (!this.__dirty && !line.__dirty) {
377	            return;
378	        }
379	
380	        const percent = line.shape.percent;
381	        const fromPos = line.pointAt(0);
382	        const toPos = line.pointAt(percent);
383	
384	        const d = vector.sub([], toPos, fromPos);
385	        vector.normalize(d, d);
386	
387	        function setSymbolRotation(symbol: ECSymbol, percent: 0 | 1) {
388	            // Fix #12388
389	            // when symbol is set to be 'arrow' in markLine,
390	            // symbolRotate value will be ignored, and compulsively use tangent angle.
391	            // rotate by default if symbol rotation is not specified
392	            const specifiedRotation = (symbol as LineECSymbol).__specifiedRotation;
393	            if (specifiedRotation == null) {
394	                const tangent = line.tangentAt(percent);
395	                symbol.attr('rotation', (percent === 1 ? -1 : 1) * Math.PI / 2 - Math.atan2(
396	                    tangent[1], tangent[0]
397	                ));
398	            }
399	            else {
400	                symbol.attr('rotation', specifiedRotation);
401	            }
402	        }
403	
404	        if (symbolFrom) {
405	            symbolFrom.setPosition(fromPos);
406	            setSymbolRotation(symbolFrom, 0);
407	            symbolFrom.scaleX = symbolFrom.scaleY = invScale * percent;
408	            symbolFrom.markRedraw();
409	        }
410	        if (symbolTo) {
411	            symbolTo.setPosition(toPos);
412	            setSymbolRotation(symbolTo, 1);
413	            symbolTo.scaleX = symbolTo.scaleY = invScale * percent;
414	            symbolTo.markRedraw();
415	        }
416	
417	        if (label && !label.ignore) {
418	            label.x = label.y = 0;
419	            label.originX = label.originY = 0;
420	
421	            let textAlign: ZRTextAlign;
422	            let textVerticalAlign: ZRTextVerticalAlign;
423	
424	            const distance = label.__labelDistance;
425	            const distanceX = distance[0] * invScale;
426	            const distanceY = distance[1] * invScale;
427	            const halfPercent = percent / 2;
428	            const tangent = line.tangentAt(halfPercent);
429	            const n = [tangent[1], -tangent[0]];
430	            const cp = line.pointAt(halfPercent);
431	            if (n[1] > 0) {
432	                n[0] = -n[0];
433	                n[1] = -n[1];
434	            }
435	            const dir = tangent[0] < 0 ? -1 : 1;
436	
437	            if (label.__position !== 'start' && label.__position !== 'end') {
438	                let rotation = -Math.atan2(tangent[1], tangent[0]);
439	                if (toPos[0] < fromPos[0]) {
440	                    rotation = Math.PI + rotation;
441	                }
442	                label.rotation = rotation;
443	            }
444	
445	            let dy;
446	            switch (label.__position) {
447	                case 'insideStartTop':
448	                case 'insideMiddleTop':
449	                case 'insideEndTop':
450	                case 'middle':
451	                    dy = -distanceY;
452	                    textVerticalAlign = 'bottom';
453	                    break;
454	
455	                case 'insideStartBottom':
456	                case 'insideMiddleBottom':
457	                case 'insideEndBottom':
458	                    dy = distanceY;
459	                    textVerticalAlign = 'top';
460	                    break;
461	
462	                default:
463	                    dy = 0;
464	                    textVerticalAlign = 'middle';
465	            }
466	
467	            switch (label.__position) {
468	                case 'end':
469	                    label.x = d[0] * distanceX + toPos[0];
470	                    label.y = d[1] * distanceY + toPos[1];
471	                    textAlign = d[0] > 0.8 ? 'left' : (d[0] < -0.8 ? 'right' : 'center');
472	                    textVerticalAlign = d[1] > 0.8 ? 'top' : (d[1] < -0.8 ? 'bottom' : 'middle');
473	                    break;
474	
475	                case 'start':
476	                    label.x = -d[0] * distanceX + fromPos[0];
477	                    label.y = -d[1] * distanceY + fromPos[1];
478	                    textAlign = d[0] > 0.8 ? 'right' : (d[0] < -0.8 ? 'left' : 'center');
479	                    textVerticalAlign = d[1] > 0.8 ? 'bottom' : (d[1] < -0.8 ? 'top' : 'middle');
480	                    break;
481	
482	                case 'insideStartTop':
483	                case 'insideStart':
484	                case 'insideStartBottom':
485	                    label.x = distanceX * dir + fromPos[0];
486	                    label.y = fromPos[1] + dy;
487	                    textAlign = tangent[0] < 0 ? 'right' : 'left';
488	                    label.originX = -distanceX * dir;
489	                    label.originY = -dy;
490	                    break;
491	
492	                case 'insideMiddleTop':
493	                case 'insideMiddle':
494	                case 'insideMiddleBottom':
495	                case 'middle':
496	                    label.x = cp[0];
497	                    label.y = cp[1] + dy;
498	                    textAlign = 'center';
499	                    label.originY = -dy;
500	                    break;
501	
502	                case 'insideEndTop':
503	                case 'insideEnd':
504	                case 'insideEndBottom':
505	                    label.x = -distanceX * dir + toPos[0];
506	                    label.y = toPos[1] + dy;
507	                    textAlign = tangent[0] >= 0 ? 'right' : 'left';
508	                    label.originX = distanceX * dir;
509	                    label.originY = -dy;
510	                    break;
511	            }
512	
513	            label.scaleX = label.scaleY = invScale;
514	            label.setStyle({
515	                // Use the user specified text align and baseline first
516	                verticalAlign: label.__verticalAlign || textVerticalAlign,
517	                align: label.__align || textAlign
518	            });
519	        }
520	    }
