65	    private _updateEffectSymbol(lineData: SeriesData, idx: number) {
66	        const itemModel = lineData.getItemModel<LineDrawModelOption>(idx);
67	        const effectModel = itemModel.getModel('effect');
68	        let size = effectModel.get('symbolSize');
