111	    private _updateEffectAnimation(
112	        lineData: SeriesData,
113	        effectModel: Model<LineDrawModelOption['effect']>,
114	        idx: number
115	    ) {
116	
117	        const symbol = this.childAt(1) as ECSymbolOnEffectLine;
118	        if (!symbol) {
119	            return;
120	        }
121	
122	        const points = lineData.getItemLayout(idx);
123	
124	        let period = effectModel.get('period') * 1000;
125	        const loop = effectModel.get('loop');
126	        const roundTrip = effectModel.get('roundTrip');
127	        const constantSpeed = effectModel.get('constantSpeed');
128	        const delayExpr = zrUtil.retrieve(effectModel.get('delay'), function (idx) {
129	            return idx / lineData.count() * period / 3;
130	        });
131	
132	        // Ignore when updating
133	        symbol.ignore = true;
134	
135	        this._updateAnimationPoints(symbol, points);
136	
137	        if (constantSpeed > 0) {
138	            period = this._getLineLength(symbol) / constantSpeed * 1000;
139	        }
140	
141	        if (period !== this._period || loop !== this._loop || roundTrip !== this._roundTrip) {
142	            symbol.stopAnimation();
