164	    private _animateSymbol(
165	        symbol: ECSymbolOnEffectLine, period: number, delayNum: number, loop: boolean, roundTrip: boolean) {
166	        if (period > 0) {
167	            symbol.__t = 0;
168	            const self = this;
169	            const animator = symbol.animate('', loop)
170	                .when(roundTrip ? period * 2 : period, {
171	                    __t: roundTrip ? 2 : 1
172	                })
173	                .delay(delayNum)
174	                .during(function () {
175	                    self._updateSymbolPosition(symbol);
176	                });
177	            if (!loop) {
178	                animator.done(function () {
179	                    self.remove(symbol);
180	                });
181	            }
182	            animator.start();
183	        }
184	    }
185	
186	    protected _getLineLength(symbol: ECSymbolOnEffectLine) {
187	        // Not so accurate
188	        return (vec2.dist(symbol.__p1, symbol.__cp1)
189	            + vec2.dist(symbol.__cp1, symbol.__p2));
190	    }
