/**
 * Verifies that the effect symbol of a lines series keeps a consistent
 * forward orientation when a non-roundTrip loop wraps around (__t hits 1
 * and jumps back to 0).
 *
 * Before the fix, `_updateSymbolPosition` used `symbol.__t < 1`, so at the
 * exact loop-end frame (__t === 1) the tangent was computed on the reversed
 * curve (the roundTrip branch), flipping the symbol rotation by ~PI.
 */
'use strict';

const path = require('path');
const assert = require('assert');

const buildDir = process.argv[2];
assert(buildDir, 'usage: node check-flip.js <compiled-build-dir>');

const EffectLine = require(
    path.join(buildDir, 'chart/helper/EffectLine.js')
).default;

// Mock symbol on a curved line p1 -> cp1 -> p2.
function makeSymbol() {
    return {
        __p1: [0, 0],
        __p2: [100, 0],
        __cp1: [50, 80],
        __t: 0,
        x: 0,
        y: 0,
        scaleX: 1,
        scaleY: 1,
        rotation: 0,
        ignore: true
    };
}

// Minimal `this` context for _updateSymbolPosition.
const ctx = {
    _symbolType: 'arrow',
    _symbolScale: [10, 10]
};

function update(symbol, t) {
    symbol.__t = t;
    EffectLine.prototype._updateSymbolPosition.call(ctx, symbol);
    return { rotation: symbol.rotation, x: symbol.x, y: symbol.y };
}

function angleDiff(a, b) {
    let d = Math.abs(a - b) % (2 * Math.PI);
    return d > Math.PI ? 2 * Math.PI - d : d;
}

// --- Non-roundTrip loop boundary -------------------------------------
// Rotation exactly at the loop end (__t === 1) must match the forward
// rotation right before the loop end (__t === 1 - eps).
const eps = 1e-6;
const beforeEnd = update(makeSymbol(), 1 - eps);
const atEnd = update(makeSymbol(), 1);

assert(
    angleDiff(atEnd.rotation, beforeEnd.rotation) < 1e-3,
    'rotation flipped at loop end: ' +
    `rotation(__t=1)=${atEnd.rotation}, rotation(__t=1-eps)=${beforeEnd.rotation}`
);

// Position must still be the line end point.
assert(Math.abs(atEnd.x - 100) < 1e-6 && Math.abs(atEnd.y - 0) < 1e-6,
    `position at __t=1 wrong: (${atEnd.x}, ${atEnd.y})`);

// Rotation right after wrap-around (__t === eps) should match rotation at
// the very start (__t === 0), i.e. the animation restarts cleanly.
const atStart = update(makeSymbol(), 0);
const afterWrap = update(makeSymbol(), eps);
assert(
    angleDiff(afterWrap.rotation, atStart.rotation) < 1e-3,
    'rotation not continuous across wrap-around: ' +
    `rotation(__t=eps)=${afterWrap.rotation}, rotation(__t=0)=${atStart.rotation}`
);

// --- roundTrip behaviour must be preserved ----------------------------
// On the return leg (__t > 1) the tangent must follow the reversed curve.
const ret = update(makeSymbol(), 1.5);
const fwd = update(makeSymbol(), 0.5);
// Both are at the same curve point (t === 0.5) but must face opposite ways.
assert(Math.abs(ret.x - fwd.x) < 1e-6 && Math.abs(ret.y - fwd.y) < 1e-6,
    'roundTrip return leg position mismatch');
assert(
    angleDiff(ret.rotation, fwd.rotation + Math.PI) < 1e-3,
    'roundTrip return leg should face the opposite direction: ' +
    `return=${ret.rotation}, forward=${fwd.rotation}`
);

console.log('PASS: effect symbol keeps forward orientation across loop end, roundTrip intact');

