/**
 * Regression test for: fix(lines): fix effect symbol flip on unidirectional
 * loop end when `roundTrip` is not enabled.
 *
 * Before the fix, `_updateSymbolPosition` used `symbol.__t < 1`, so at the
 * exact loop-end frame (__t === 1) the tangent was computed on the reversed
 * curve (the roundTrip-only branch), flipping the symbol rotation by ~PI for
 * one frame whenever a looping non-roundTrip effect crosses the loop point.
 *
 * Run with:
 *   npx jest --config test/ut/jest.config.cjs --coverage=false \
 *       --roots /workspace/agent_tests --testMatch '**\/*.test.ts' \
 *       -t 'effect symbol loop flip'
 */
import EffectLine from '../../../src/chart/helper/EffectLine';

type MockSymbol = {
    __p1: number[]
    __p2: number[]
    __cp1: number[]
    __t: number
    x: number
    y: number
    scaleX: number
    scaleY: number
    rotation: number
    ignore: boolean
};

function makeSymbol(): MockSymbol {
    return {
        __p1: [0, 0],
        __p2: [100, 0],
        __cp1: [50, 80],
        __t: 0,
        x: 0,
        y: 0,
        scaleX: 1,
        scaleY: 1,
        rotation: 0,
        ignore: true
    };
}

// Minimal `this` context for _updateSymbolPosition.
const ctx = {
    _symbolType: 'arrow',
    _symbolScale: [10, 10]
};

function update(t: number) {
    const symbol = makeSymbol();
    symbol.__t = t;
    (EffectLine.prototype as any)._updateSymbolPosition.call(ctx, symbol);
    return symbol;
}

function angleDiff(a: number, b: number) {
    let d = Math.abs(a - b) % (2 * Math.PI);
    return d > Math.PI ? 2 * Math.PI - d : d;
}

describe('lines effect symbol loop flip', function () {

    it('keeps forward orientation across loop end when roundTrip is off', function () {
        const eps = 1e-6;
        const beforeEnd = update(1 - eps);
        const atEnd = update(1);

        // Rotation exactly at the loop end must match the forward rotation
        // right before it (no 180-degree flip on the wrap-around frame).
        expect(angleDiff(atEnd.rotation, beforeEnd.rotation)).toBeLessThan(1e-3);

        // Position must still be the line end point.
        expect(atEnd.x).toBeCloseTo(100, 6);
        expect(atEnd.y).toBeCloseTo(0, 6);

        // Rotation right after wrap-around matches the rotation at the start.
        const atStart = update(0);
        const afterWrap = update(eps);
        expect(angleDiff(afterWrap.rotation, atStart.rotation)).toBeLessThan(1e-3);
    });

    it('still reverses orientation on the roundTrip return leg', function () {
        const forward = update(0.5);
        const back = update(1.5);

        // Same curve point, but the return leg must face the opposite way.
        expect(back.x).toBeCloseTo(forward.x, 6);
        expect(back.y).toBeCloseTo(forward.y, 6);
        expect(angleDiff(back.rotation, forward.rotation + Math.PI)).toBeLessThan(1e-3);
    });
});

